  }
  const act = aS/tw, inh = iS/tw, harm = hrm/tw;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2 + Math.sin(sx*0.08+sy*0.06-t*1.5)*0.5 + Math.sin(sx*0.12-sy*0.1+t*2.2)*0.25 + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2;
