  const pal = [[4,10,45],[8,30,72],[12,60,100],[18,100,118],[30,145,125],[80,180,110],[150,200,90],[210,195,75],[235,165,65],[235,125,75],[210,85,85],[170,55,95],[110,35,85],[55,22,68],[20,14,50],[4,10,45]];
